<template><div class="task-page"><el-card><template #header><div class="task-card-header"><span>学习总结</span><el-button type="primary" @click="visible=true">新建总结</el-button></div></template><el-form inline><el-form-item label="类型"><el-select v-model="type" clearable style="width:140px" @change="load"><el-option v-for="o in types" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-button @click="load">查询</el-button></el-form><el-collapse><el-collapse-item v-for="s in summaries" :key="s.id" :title="`${typeName(s.summaryType)} · ${s.periodStart} 至 ${s.periodEnd}`"><div class="summary-grid"><div><b>核心收获</b><p>{{s.gains||'-'}}</p></div><div><b>遗留问题</b><p>{{s.problems||'-'}}</p></div><div><b>改进动作</b><p>{{s.improvements||'-'}}</p></div></div><pre class="markdown-preview">{{s.markdownContent}}</pre></el-collapse-item></el-collapse><el-empty v-if="!summaries.length" description="暂无学习总结"/></el-card>
<el-dialog v-model="visible" title="新建学习总结" width="820px"><el-form :model="form" label-width="90px"><el-row :gutter="16"><el-col :span="12"><el-form-item label="关联计划"><el-select v-model="form.planId" clearable style="width:100%"><el-option v-for="p in plans" :key="p.id" :label="p.title" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="总结类型"><el-select v-model="form.summaryType"><el-option v-for="o in types" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-form-item label="周期开始"><el-date-picker v-model="form.periodStart" value-format="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="12"><el-form-item label="周期结束"><el-date-picker v-model="form.periodEnd" value-format="YYYY-MM-DD"/></el-form-item></el-col></el-row><el-form-item label="核心收获"><el-input v-model="form.gains" type="textarea"/></el-form-item><el-form-item label="遗留问题"><el-input v-model="form.problems" type="textarea"/></el-form-item><el-form-item label="改进动作"><el-input v-model="form.improvements" type="textarea"/></el-form-item><el-form-item label="标签"><el-input v-model="form.tags"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="Markdown"><el-input v-model="form.markdownContent" type="textarea" :rows="12"/></el-form-item></el-col><el-col :span="12"><div class="preview-title">实时预览</div><pre class="markdown-preview editor-preview">{{form.markdownContent}}</pre></el-col></el-row></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{onMounted,reactive,ref}from'vue';import{createLearningSummary,listLearningSummaries,listPlans,type LearningPlan,type LearningSummary}from'@/api/learning';const types=[{label:'周总结',value:'WEEKLY'},{label:'月总结',value:'MONTHLY'},{label:'阶段总结',value:'STAGE'}],type=ref(''),summaries=ref<LearningSummary[]>([]),plans=ref<LearningPlan[]>([]),visible=ref(false);const today=new Date().toISOString().slice(0,10);const form=reactive({planId:undefined as number|undefined,summaryType:'WEEKLY',periodStart:today,periodEnd:today,gains:'',problems:'',improvements:'',markdownContent:'# 本期总结\n\n',tags:''});function typeName(v:string){return types.find(x=>x.value===v)?.label||v;}async function load(){summaries.value=(await listLearningSummaries({type:type.value||undefined})).data;}async function save(){if(!form.markdownContent.trim()){ElMessage.warning('请输入总结正文');return;}await createLearningSummary(form);ElMessage.success('总结已保存');visible.value=false;await load();}onMounted(async()=>{plans.value=(await listPlans()).data;await load();});</script>